#include <bits/stdc++.h>
using namespace std;

struct trie {
  using ar = array<int, 26>;
  vector<ar> pos;
  ar def;
  int now_sz;
  long long ans;
  vector<int> cnt;
  trie() = default;
  trie(int len) {
    pos.reserve(len + 1);
    cnt.reserve(len + 1);
    def.fill(-1);
    now_sz = ans = 0;
    make_node();
  }
  int make_node() {
    pos.push_back(def);
    cnt.push_back(0);
    return now_sz++;
  }
  void add(string &s) {
    int now = 0;
    for(int i = 0; i < (int)s.size(); i++) {
      int d = s[i] - 'a';
      int &nx = pos[now][d];
      if(nx == -1)
        nx = make_node();
      now = nx;
      ans += cnt[now]++;
    }
  }
};

int main() {
  int n;
  cin >> n;
  trie tr(300000);
  for(int i = 0; i < n; i++) {
    string s;
    cin >> s;
    tr.add(s);
  }
  cout << tr.ans << endl;
}

use proconio::input;

fn main() {
    input! {
        n: usize,
        mut s: [String; n],
    }
    s.sort_unstable();
    s.push(String::new());
    let mut stack = Vec::new();
    let mut ans = 0;
    for (i, s) in s.iter().enumerate() {
        let lcp = stack
            .iter()
            .zip(s.chars())
            .take_while(|&(&(c, _), d)| c == d)
            .count();
        while stack.len() > lcp {
            let (_, start) = stack.pop().unwrap();
            ans += (i - start) * (i - start - 1) / 2;
        }
        for c in s[lcp..].chars() {
            stack.push((c, i));
        }
    }
    println!("{}", ans);
}

#include<bits/stdc++.h>
using namespace std;
#include<atcoder/all>
int main(){
    int n;cin>>n;
    vector<string> s(n);for(auto&e:s)cin>>e;
    sort(s.begin(),s.end());
    vector<pair<int,int>> a;
    for(int i=0;i<n-1;i++){
        int idx=0;
        while(idx<min(s[i].size(),s[i+1].size())&&s[i][idx]==s[i+1][idx])idx++;
        a.push_back({idx,i});
    }
    sort(a.begin(),a.end());reverse(a.begin(),a.end());
    atcoder::dsu d(n);
    long ans=0;
    for(auto[idx,i]:a){
        ans+=long(d.size(i))*d.size(i+1)*idx;
        d.merge(i,i+1);
    }
    cout<<ans<<endl;
}
